<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue';
import {pmsApi} from './api';
import {withoutPmsLoader} from './loading';
import {useBoardDrag} from './useBoardDrag';
import PmsKanbanCard from './PmsKanbanCard.vue';
import PmsMyWorkAssignees from './PmsMyWorkAssignees.vue';
import PmsTaskDetail from './PmsTaskDetail.vue';
const props=defineProps<{scope:string;ownerId:number;csrf?:string;permissions:string[]}>();
const assignment=ref<any>(null),assignmentUsers=ref<any[]>([]);
const data=ref<any>(null),error=ref(''),busy=ref(false),issue=ref<number|null>(null),action=ref('');
const q=new URLSearchParams(location.search);const filters=ref({project:q.get('project')||'',department:q.get('department')||'',sprint:q.get('sprint')||'all'});
const columns=[{id:'pending',name:'To Do',color:'secondary'},{id:'in_progress',name:'In Progress',color:'primary'},{id:'in_review',name:'Review',color:'warning'},{id:'completed',name:'Completed',color:'success'}];
const {dragging,target,start,over,leave,clear}=useBoardDrag();let version=0,disposed=false;
const can=(k:string)=>props.permissions.includes('*')||props.permissions.includes(k);
async function load(quiet=false){const token=++version;error.value='';try{const query=new URLSearchParams({scope:props.scope,id:String(props.ownerId),...filters.value});const request=()=>pmsApi('hierarchy-board?'+query);const result=await(quiet?withoutPmsLoader(request):request());if(!disposed&&token===version)data.value=result.data;}catch(e){if(!disposed&&token===version)error.value=(e as Error).message;}}
function filter(field:string){if(field==='project')filters.value.department='';if(field!=='sprint')filters.value.sprint='all';const url=new URL(location.href);for(const [key,value]of Object.entries(filters.value))value?url.searchParams.set(key,value):url.searchParams.delete(key);history.replaceState(null,'',url);void load();}
async function open(id:number,kind=''){if(kind==='assign'){error.value='';assignmentUsers.value=[];const task=data.value.tasks.find((t:any)=>t.id===id);assignment.value=task;try{const response=await withoutPmsLoader(()=>pmsApi('tasks/'+id+'/assignees'));if(!disposed&&assignment.value?.id===id)assignmentUsers.value=response.users;}catch(e){if(!disposed)error.value=(e as Error).message;}return;}issue.value=id;action.value=kind;}
async function drop(status:string){const id=dragging.value;clear();if(!id||busy.value||!can('task-status'))return;busy.value=true;error.value='';try{const result=await withoutPmsLoader(()=>pmsApi('hierarchy-board/tasks/'+id+'/status',props.csrf,'PATCH',{status}));const task=data.value.tasks.find((t:any)=>t.id===id);if(task&&result.task)Object.assign(task,result.task);}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function changed(e:Event){const id=Number((e as CustomEvent).detail?.project_id);if(id&&data.value&&!data.value.projects.some((p:any)=>p.id===id))return;if(!busy.value&&!issue.value&&!assignment.value)void load(true);}
onMounted(()=>{void load();window.addEventListener('pms:changed',changed);});onUnmounted(()=>{disposed=true;version++;window.removeEventListener('pms:changed',changed);});
</script>
<template><section class="jira-shell pms-hierarchy-board"><div class="jira-toolbar mb-3"><div><div class="text-muted small mb-1">{{scope.toUpperCase()}} / {{data?.owner.name}}</div><h3 class="mb-1">Sprint board</h3><small class="text-muted">All accessible tasks across {{scope==='project'?'this project\'s departments':scope==='client'?'this client\'s projects and departments':'this company\'s clients, projects, and departments'}}.</small></div></div><p v-if="error" class="notice admin-error" role="alert">{{error}}</p><template v-if="data"><div class="filter-card p-3 mb-3 pms-hierarchy-filters"><label v-if="scope!=='project'">Project<select aria-label="Board project" v-model="filters.project" @change="filter('project')"><option value="">All projects</option><option v-for="p in data.projects" :key="p.id" :value="String(p.id)">{{p.name}}</option></select></label><label>Department<select aria-label="Board department" v-model="filters.department" @change="filter('department')"><option value="">All departments</option><option v-for="d in data.departments" :key="d.id" :value="String(d.id)">{{d.dept_name}}</option></select></label><label>Sprint<select aria-label="Board sprint" v-model="filters.sprint" @change="filter('sprint')"><option value="all">All sprints and backlog</option><option value="backlog">Backlog</option><option v-for="s in data.sprints" :key="s.id" :value="String(s.id)">{{s.name}} &middot; {{s.project?.name}} &middot; {{s.status}}</option></select></label></div><div class="d-flex gap-2 flex-wrap mb-3 pms-board-metrics"><div v-for="m in [{key:'projects',label:'Projects'},{key:'tasks',label:'Visible tasks'},{key:'sprints',label:'Sprints'},{key:'backlog',label:'Backlog tasks'}]" :key="m.key" class="metric-card"><div class="small text-muted">{{m.label}}</div><div class="metric-value">{{data.stats[m.key]}}</div></div></div><div class="jira-board"><section v-for="c in columns" :key="c.id" class="jira-column" :class="{'drag-over':target===c.id}" @dragover.prevent="over(c.id,$event)" @dragleave="leave(c.id,$event)" @drop.prevent="drop(c.id)"><div class="jira-column-title"><span class="badge" :class="'bg-label-'+c.color">{{c.name}}</span><span class="column-count badge bg-white text-dark">{{data.tasks.filter((t:any)=>t.status===c.id).length}}</span></div><div class="jira-task-list"><PmsKanbanCard v-for="t in data.tasks.filter((t:any)=>t.status===c.id)" :key="t.id" :task="t" show-project show-hierarchy :permissions="permissions" :busy="busy" :class="{dragging:dragging===t.id}" @drag="start" @open="open($event)" @edit="open($event,'edit')" @assign="open($event,'assign')" @delete="open($event,'delete')" @handoff="open($event,'handoff')" @transfer="open($event,'transfer')"/><div v-if="!data.tasks.some((t:any)=>t.status===c.id)" class="jira-empty">No tasks in this stage</div></div></section></div></template><PmsMyWorkAssignees v-if="assignment" :task="assignment" :users="assignmentUsers" :csrf="csrf" @close="assignment=null" @updated="load(true)"/><PmsTaskDetail v-if="issue" :id="issue" :initial-task="action==='edit'?data?.tasks.find((t:any)=>t.id===issue):undefined" :initial-action="action" :csrf="csrf" :permissions="permissions" @close="issue=null;action=''" @updated="load(true)"/></section></template>
